import{_ as a,o as t,c as i,a5 as n}from"./chunks/framework.BwlBv862.js";const m=JSON.parse('{"title":"Téléchargements et mises à jour","description":"","frontmatter":{"title":"Téléchargements et mises à jour","docId":"user.start.updates","translationKey":"user.start.updates","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6b92351b3ee8eb1b0745db65bbddb3eab21f4ae0a9945795c94147c9ca347e73","translationRevision":"32717b10c0edf621049e1626bbe7a802dc9b31f0d81f58e884806f94c8bed5ca","order":40},"headers":[],"relativePath":"fr/user/updates.md","filePath":"fr/user/updates.md","lastUpdated":1794611623000}'),s={name:"fr/user/updates.md"};function r(o,e,l,u,c,d){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="downloads-and-updates" tabindex="-1">Téléchargements et mises à jour <a class="header-anchor" href="#downloads-and-updates" aria-label="Permalink to &quot;Téléchargements et mises à jour {#downloads-and-updates}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Choisir le bon canal de publication et effectuer une mise à jour sans confondre sa recherche avec une installation automatique. Fermez les sessions actives et sauvegardez les données locales avant de changer de version, surtout lorsqu’une migration de base de données est documentée.</p><h2 id="select-a-channel" tabindex="-1">Choisir un canal <a class="header-anchor" href="#select-a-channel" aria-label="Permalink to &quot;Choisir un canal {#select-a-channel}&quot;">​</a></h2><p>La <a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">liste des versions</a> distingue les versions stables des préversions. Une version candidate telle que <code>-rc</code> est destinée aux vérifications. Le système de mise à jour distingue les flux stable et bêta ; il authentifie les métadonnées signées avant de proposer une version. Un fichier JSON non signé ou un installateur modifié ne constitue pas une mise à jour acceptée.</p><h2 id="check-and-install" tabindex="-1">Rechercher et installer <a class="header-anchor" href="#check-and-install" aria-label="Permalink to &quot;Rechercher et installer {#check-and-install}&quot;">​</a></h2><ol><li>Ouvrez <strong>Settings → General</strong> et consultez l’état du système de mise à jour et la version installée.</li><li>Lancez la vérification disponible. Les compilations sans clé publique ou capacité de flux configurée indiquent que la vérification est indisponible.</li><li>Lisez les notes de version et choisissez le paquet de votre plateforme.</li><li>Lorsque la compilation propose un téléchargement ou un transfert manuel, suivez ce parcours. Le processus active les vérifications authentifiées seulement si la variable de clé publique est configurée ; l’installation automatique a des conditions supplémentaires.</li><li>Pour une mise à jour manuelle, fermez TikTools, remplacez ou installez le paquet complet vérifié, puis rouvrez-le. Conservez le répertoire de données séparément des fichiers de l’application.</li></ol><h2 id="expected-result" tabindex="-1">Résultat attendu <a class="header-anchor" href="#expected-result" aria-label="Permalink to &quot;Résultat attendu {#expected-result}&quot;">​</a></h2><p>Après redémarrage, l’application indique la version choisie et peut lire le profil local attendu. Les paquets portables ZIP/TAR nécessitent un remplacement manuel. Les dispositions inconnues ou extraites peuvent aussi imposer une procédure manuelle, même lorsqu’un installateur AppImage existe.</p><h2 id="recovery-and-limitations" tabindex="-1">Récupération et limites <a class="header-anchor" href="#recovery-and-limitations" aria-label="Permalink to &quot;Récupération et limites {#recovery-and-limitations}&quot;">​</a></h2><p>Une vérification de signature échouée signifie que la mise à jour a échoué ; téléchargez une nouvelle copie officielle et vérifiez les sommes de contrôle de la version. Ne contournez pas la vérification. Le remplacement automatique AppImage et le transfert NSIS ont des conditions de compilation distinctes et sont expérimentaux. Il n’existe aucun retour arrière automatique général. Revenir à un ancien binaire n’annule pas la migration d’un schéma SQLite.</p><p>Signalez la version installée, le format du paquet et l’erreur de mise à jour issue de Diagnostics. Ne joignez pas de clés de signature, jetons d’invitation ou données de compte. Le <a href="./installation.html">guide d’installation</a> décrit les dispositions de paquet prises en charge.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Détails de fonctionnement {#operational-details}&quot;">​</a></h2><p>La capacité updater est fixée à la compilation. Les vérifications exigent feed et clé publique. AppImage automatique exige aussi la condition commune d’installation et une installation reconnue ; NSIS exige cette même condition ET sa condition spécifique. Les variables après installation n’activent pas ces options compilées. Portable/extrait/inconnu utilise le remplacement manuel. Vérifiez version, redémarrage et profil après installation ; téléchargement, checksum ou lancement ne prouvent pas son achèvement.</p>',14)])])}const h=a(s,[["render",r]]);export{m as __pageData,h as default};
